// C++ program to find the sum of elements in an array using recursion 

#include <iostream> 
using namespace std; 

// Recursive function to find the sum of elements in an array 
int sum_array(int arr[], int size) 
{ 
    if (size == 0) // base case: when array size is 0, the sum is 0 
        return 0; 

    // sum of first n elements = sum of first n-1 elements + nth element
    // recursive call to sum the elements from 0 to size-1 and adding the element at size-1
    return sum_array(arr, size-1) + arr[size-1]; 
} 

int main() 
{ 
    int size; 
    cout << "Enter the size of the array: "; 
    cin >> size; 

