function isValidDate(dateString) {
  // Trim any leading or trailing white spaces
  dateString = dateString.trim();

  // Match the format yyyy-mm-dd using regular expression
  const regex = /^(\d{4})-(\d{2})-(\d{2})$/;

  // Check if the string matches the regular expression
  if (!regex.test(dateString)) return false;

  // Extract the year, month, and day from the string using destructuring
  const [, year, month, day] = dateString.match(regex);

  // Convert year, month, and day to numbers
  const yyyy = parseInt(year, 10);
  const mm = parseInt(month, 10);
  const dd = parseInt(day, 10);

  // Validate that year is in the range of 1000 to 9999
  if (yyyy < 1000 || yyyy > 9999) return false;

  // Validate that month is between 01 and 12
  if (mm < 1 || mm > 12) return false;

  // Validate that day is valid for the given month and year
  const daysInMonth = new Date(yyyy, mm, 0).getDate();
  if (dd < 1 || dd > daysInMonth) return false;

  // Handle leap years correctly
  if (mm === 2 && dd === 29 && ! (yyyy % 4 === 0 && (yyyy % 100 !== 0 || yyyy % 400 === 0))) {
    return false;
  }

  // The date string is valid
  return true;
}
```

