<?php
function isAlphabetic($string) {
    if (!is_string($string)) {
        throw new InvalidArgumentException('Input must be a string');
    }

    $isAlphabetic = true;
    for ($i = 0; $i < strlen($string); $i++) {
        $char = $string[$i];
        if (!ctype_alpha($char)) {
            $isAlphabetic = false;
            break;
        }
    }

    return $isAlphabetic;
}

// Usage example
$string1 = 'HeLLo';
$string2 = 'HeLLo#WorLD';

try {
    if (isAlphabetic($string1)) {
        echo "$string1 is purely alphabetic\n";
    } else {
        echo "$string1 is not purely alphabetic\n";
    }

    if (isAlphabetic($string2)) {
        echo "$string2 is purely alphabetic\n";
    } else {
        echo "$string2 is not purely alphabetic\n";
    }
} catch (InvalidArgumentException $e) {
    echo $e->getMessage();
}
```

